<div class="page-shell"><header class="page-hero wrap"><span class="eyebrow">Community forum</span><h1>Start a discussion</h1><p>Keep contributions factual, respectful and free of private personal information.</p></header><form class="form-card wrap" method="post" action="<?=url('discussions')?>"><?=csrf_field()?><div class="field"><label for="title">Discussion title</label><input id="title" name="title" minlength="8" maxlength="180" required></div><div class="field"><label for="category_id">Category</label><select id="category_id" name="category_id" required><option value="">Select</option><?php foreach($categories as $c):?><option value="<?=e($c['id'])?>"><?=e($c['name'])?></option><?php endforeach;?></select></div><div class="field"><label for="body">Opening post</label><textarea id="body" name="body" minlength="30" required></textarea></div><button class="pill pill-dark">Submit for review</button></form></div>
